    // 71. Bidirectional Parent-Child Inter-Process Communication
    {
        let mut p_p2c = [0i32; 2];
        let mut p_c2p = [0i32; 2];
        if portix_rt::syscall::sys_pipe(p_p2c.as_mut_ptr()) == 0 && portix_rt::syscall::sys_pipe(p_c2p.as_mut_ptr()) == 0 {
            let pid = portix_rt::fork();
            if pid == 0 {
                // Child: closes unused endpoints
                let _ = portix_rt::syscall::sys_close(p_p2c[1]);
                let _ = portix_rt::syscall::sys_close(p_c2p[0]);
                let mut buf = [0u8; 16];
                let _ = portix_rt::syscall::sys_read(p_p2c[0], buf.as_mut_ptr(), 16);
                let _ = portix_rt::syscall::sys_write(p_c2p[1], b"PONG_RESPONSE_OK\0".as_ptr(), 16);
                let _ = portix_rt::syscall::sys_close(p_p2c[0]);
                let _ = portix_rt::syscall::sys_close(p_c2p[1]);
                portix_rt::exit(0);
            } else if pid > 0 {
                // Parent: closes unused endpoints
                let _ = portix_rt::syscall::sys_close(p_p2c[0]);
                let _ = portix_rt::syscall::sys_close(p_c2p[1]);
                let _ = portix_rt::syscall::sys_write(p_p2c[1], b"PING_REQUEST_GO!\0".as_ptr(), 16);
                let _ = portix_rt::syscall::sys_close(p_p2c[1]);
                let mut status = 0i32;
                let _ = portix_rt::waitpid(pid as i32, &mut status, 0);
                let mut reply = [0u8; 16];
                let n = portix_rt::syscall::sys_read(p_c2p[0], reply.as_mut_ptr(), 16);
                let _ = portix_rt::syscall::sys_close(p_c2p[0]);
                if n == 16 && &reply[..16] == b"PONG_RESPONSE_OK" {
                    println!("[TEST 75] Bidirectional parent-child IPC pipe verified: PING/PONG intact");
                } else {
                    println!("[TEST 75] Bidirectional IPC failed: n={} reply='{:?}'", n, &reply[..n.max(0) as usize]);
                }
            } else {
                println!("[TEST 75] fork failed");
            }
        } else {
            println!("[TEST 75] sys_pipe failed");
        }
    }

