            let _ = portix_rt::syscall::sys_lseek(fd, 2, 0); // pos = 2
            let pwres = portix_rt::pwrite(fd, b"ZZ", 6); // pwrite at offset 6: overwrite first two B's
            let _ = portix_rt::syscall::sys_write(fd, b"YY".as_ptr(), 2);
            let _ = portix_rt::syscall::sys_lseek(fd, 0, 0);
