    // 532. sys_getdents64 on directory descriptor collected 64-bit dirents
    {
        // [CICLO 49] Prueba real de readdir(): bucle hasta 0 con un búfer
        // pequeño (obliga a varias llamadas), d_reclen coherente, sin nombres
        // repetidos, y una llamada más tras agotar devuelve 0. Con el antiguo
        // getdents64 sin cursor (siempre el listado completo) esto no termina.
        let fd = portix_rt::syscall::sys_open(b"/etc\0".as_ptr(), 0);
        let mut d_buf = [0u8; 96];
        let mut llamadas = 0usize; let mut entradas = 0usize; let mut repetido = false; let mut mal_formado = false;
        let mut vistos: [u64; 64] = [0; 64];
        let mut n = -1i64;
        if fd >= 0 {
            loop {
                n = portix_rt::syscall::sys_getdents64(fd as i32, d_buf.as_mut_ptr(), d_buf.len());
                llamadas += 1;
                if n <= 0 || llamadas > 64 { break; }
                let mut off = 0usize;
                while off + 19 < n as usize {
                    let reclen = u16::from_le_bytes([d_buf[off + 16], d_buf[off + 17]]) as usize;
                    if reclen < 20 || off + reclen > n as usize { mal_formado = true; break; }
                    let ino = u64::from_le_bytes([d_buf[off], d_buf[off+1], d_buf[off+2], d_buf[off+3], d_buf[off+4], d_buf[off+5], d_buf[off+6], d_buf[off+7]]);
                    if ino == 0 { mal_formado = true; }
                    if entradas < 64 { if vistos[..entradas].contains(&ino) { repetido = true; } vistos[entradas] = ino; }
                    entradas += 1;
                    off += reclen;
                }
            }
            let otra = portix_rt::syscall::sys_getdents64(fd as i32, d_buf.as_mut_ptr(), d_buf.len());
            portix_rt::syscall::sys_close(fd as i32);
            if n == 0 && otra == 0 && llamadas >= 2 && entradas >= 3 && !repetido && !mal_formado {
                println!("[TEST 532] sys_getdents64 populated 64-bit directory entries successfully ({} entradas en {} llamadas, fin=0)", entradas, llamadas);
            } else {
                println!("[TEST 532] sys_getdents64 failed: n={} otra={} llamadas={} entradas={} repetido={} mal_formado={}", n, otra, llamadas, entradas, repetido, mal_formado);
            }
        } else {
            println!("[TEST 532] sys_getdents64 failed: fd={}", fd);
        }
    }

