    // 615. sys_recvmsg receives datagram via msghdr structure
    {
        // [CICLO 48] Antes: recvmsg sobre un UDP sin datos "recibia" 0 bytes
        // (el syscall era ficticio). Ahora prueba REAL: sendmsg con dos iovec
        // ("abc","defg") y recvmsg con dos iovec de 4 y 8 bytes sobre un
        // socketpair: los 7 bytes llegan repartidos como exige scatter/gather,
        // y un UDP sin datos ni pares devuelve EAGAIN, no un exito vacio.
        let mut sv = [0i32; 2];
        let rsp = portix_rt::syscall::sys_socketpair(1, 1, 0, sv.as_mut_ptr());
        let a = b"abc"; let bb = b"defg";
        let iovs = [portix_rt::IoVec { iov_base: a.as_ptr() as *mut u8, iov_len: 3 }, portix_rt::IoVec { iov_base: bb.as_ptr() as *mut u8, iov_len: 4 }];
        let msg = portix_rt::MsgHdr { msg_name: 0, msg_namelen: 0, msg_iov: iovs.as_ptr() as usize, msg_iovlen: 2, msg_control: 0, msg_controllen: 0, msg_flags: 0 };
        let sent = portix_rt::syscall::sys_sendmsg(sv[1], &msg as *const _, 0);
        let mut r1 = [0u8; 4]; let mut r2 = [0u8; 8];
        let riovs = [portix_rt::IoVec { iov_base: r1.as_mut_ptr(), iov_len: 4 }, portix_rt::IoVec { iov_base: r2.as_mut_ptr(), iov_len: 8 }];
        let mut rmsg = portix_rt::MsgHdr { msg_name: 0, msg_namelen: 0, msg_iov: riovs.as_ptr() as usize, msg_iovlen: 2, msg_control: 0, msg_controllen: 0, msg_flags: 0 };
        let ret = portix_rt::syscall::sys_recvmsg(sv[0], &mut rmsg, 0);
        portix_rt::syscall::sys_close(sv[0]); portix_rt::syscall::sys_close(sv[1]);
        let sock = portix_rt::syscall::sys_socket(2, 2, 0);
        let udp = if sock >= 0 { portix_rt::syscall::sys_recvmsg(sock as i32, &mut rmsg, 0) } else { -1 };
        if sock >= 0 { portix_rt::syscall::sys_close(sock as i32); }
        if rsp == 0 && sent == 7 && ret == 7 && &r1 == b"abcd" && &r2[..3] == b"efg" && udp == -11 {
            println!("[TEST 615] sys_recvmsg real: scatter/gather de 7 bytes en dos iovec (abcd|efg) por socketpair y EAGAIN en UDP sin datos verified");
        } else {
            println!("[TEST 615] sys_recvmsg failed: sp={} sent={} ret={} r1={:?} r2={:?} udp={}", rsp, sent, ret, r1, &r2[..3], udp);
        }
    }

