    // 1594. sys_rt_sigsuspend valid invocation returns -EINTR verified
    {
        // [T-001/FIFO] sigsuspend REAL (POSIX): con SIGALRM bloqueada se arma
        // alarm(1); sigsuspend(mask=0) la desbloquea de forma atomica y espera.
        // Se exige: -EINTR, manejador ejecutado (14), >= ~1 s de espera real, y
        // la mascara PREVIA (SIGALRM bloqueada) restaurada al volver.
        SIG_LAST.store(0, Ordering::SeqCst);
        let act = portix_rt::syscall::SigAction { sa_handler: usr1_handler as usize, sa_flags: 0, sa_mask: 0 };
        let _ = portix_rt::sigaction(14, Some(&act), None);
        let _ = portix_rt::sigprocmask(portix_rt::syscall::SIG_SETMASK, Some(1u64 << 14), None);
        let t0 = portix_rt::syscall::sys_uptime();
        let _ = portix_rt::alarm(1);
        let mask = 0u64;
        let res = portix_rt::syscall::sys_rt_sigsuspend(&mask as *const _ as usize, 8);
        let dt = portix_rt::syscall::sys_uptime().wrapping_sub(t0);
        let mut despues = 0u64;
        let _ = portix_rt::sigprocmask(portix_rt::syscall::SIG_BLOCK, None, Some(&mut despues));
        let _ = portix_rt::sigprocmask(portix_rt::syscall::SIG_SETMASK, Some(0), None);
        let _ = portix_rt::sysaction_default(14);
        if res == -4 && SIG_LAST.load(Ordering::SeqCst) == 14 && dt >= 50 && despues & (1u64 << 14) != 0 {
            println!("[TEST 1594] sys_rt_sigsuspend valid invocation returns -EINTR verified");
        } else {
            println!("[TEST 1594] unexpected: {} (handler={} ticks={} mascara_despues=0x{:x})", res, SIG_LAST.load(Ordering::SeqCst), dt, despues);
        }
        }

