    // 2813. inotify Descriptor Integration with epoll/poll Readiness
    {
        // [CICLO 48] inotify REAL: vigilancia sobre /tmp; crear, escribir y
        // borrar un fichero genera IN_CREATE, IN_MODIFY e IN_DELETE con el
        // nombre base; poll y epoll solo indican POLLIN cuando hay eventos;
        // lectura no bloqueante vacia -> EAGAIN; rm_watch -> IN_IGNORED y
        // despues EINVAL; ruta inexistente -> ENOENT; fd no inotify -> EINVAL.
        let ifd = portix_rt::syscall::sys_inotify_init1(0x800);
        let mut buf = [0u8; 512];
        let vacio = portix_rt::syscall::sys_read(ifd, buf.as_mut_ptr(), 512);
        let wd = portix_rt::syscall::sys_inotify_add_watch(ifd, b"/tmp\0".as_ptr(), 0x100 | 0x2 | 0x200);
        let noent = portix_rt::syscall::sys_inotify_add_watch(ifd, b"/tmp/no-existe-2813\0".as_ptr(), 0x100);
        let mut pfd = portix_rt::syscall::PollFd { fd: ifd, events: 1, revents: 0 };
        let p0 = portix_rt::syscall::sys_poll(&mut pfd as *mut _, 1, 0);
        let epfd = portix_rt::syscall::sys_epoll_create1(0) as i32;
        let ev = portix_rt::syscall::EpollEvent { events: 1, data: 2813 };
        let ectl = portix_rt::syscall::sys_epoll_ctl(epfd, 1, ifd, &ev as *const _);
        let mut evs = [portix_rt::syscall::EpollEvent { events: 0, data: 0 }; 4];
        let e0 = portix_rt::syscall::sys_epoll_wait(epfd, evs.as_mut_ptr(), 4, 0);
        let noino = portix_rt::syscall::sys_inotify_add_watch(epfd, b"/tmp\0".as_ptr(), 0x100);
        let f = portix_rt::syscall::sys_open(b"/tmp/ino2813\0".as_ptr(), 0x41 | 0x200) as i32;
        let w = portix_rt::syscall::sys_write(f, b"x".as_ptr(), 1);
        portix_rt::syscall::sys_close(f);
        let u = portix_rt::syscall::sys_unlink(b"/tmp/ino2813\0".as_ptr());
        pfd.revents = 0;
        let p1 = portix_rt::syscall::sys_poll(&mut pfd as *mut _, 1, 0);
        let e1 = portix_rt::syscall::sys_epoll_wait(epfd, evs.as_mut_ptr(), 4, 0);
        let n = portix_rt::syscall::sys_read(ifd, buf.as_mut_ptr(), 512);
        // Decodificar struct inotify_event {wd, mask, cookie, len, name[len]}
        let mut masks = [0u32; 4]; let mut nombres_ok = true; let mut wds_ok = true; let mut cnt = 0usize; let mut off = 0usize;
        while n > 0 && off + 16 <= n as usize && cnt < 4 {
            let ewd = i32::from_ne_bytes([buf[off], buf[off+1], buf[off+2], buf[off+3]]);
            let m = u32::from_ne_bytes([buf[off+4], buf[off+5], buf[off+6], buf[off+7]]);
            let l = u32::from_ne_bytes([buf[off+12], buf[off+13], buf[off+14], buf[off+15]]) as usize;
            if ewd != wd { wds_ok = false; }
            if l < 8 || &buf[off+16..off+16+7] != b"ino2813" || buf[off+16+7] != 0 { nombres_ok = false; }
            masks[cnt] = m; cnt += 1; off += 16 + l;
        }
        let rm = portix_rt::syscall::sys_inotify_rm_watch(ifd, wd);
        let n2 = portix_rt::syscall::sys_read(ifd, buf.as_mut_ptr(), 512);
        let m_ign = if n2 >= 16 { u32::from_ne_bytes([buf[4], buf[5], buf[6], buf[7]]) } else { 0 };
        let rm2 = portix_rt::syscall::sys_inotify_rm_watch(ifd, wd);
        portix_rt::syscall::sys_close(epfd); portix_rt::syscall::sys_close(ifd);
        if ifd >= 0 && vacio == -11 && wd > 0 && noent == -2 && p0 == 0 && epfd >= 0 && ectl == 0 && e0 == 0 && noino == -22
            && f >= 0 && w == 1 && u == 0 && p1 == 1 && (pfd.revents & 1) != 0 && e1 == 1 && evs[0].data == 2813
            && cnt == 3 && masks[0] == 0x100 && masks[1] == 0x2 && masks[2] == 0x200 && nombres_ok && wds_ok
            && rm == 0 && n2 == 16 && m_ign == 0x8000 && rm2 == -22 {
            println!("[TEST 2813] inotify real: vigilancia en /tmp, eventos IN_CREATE/IN_MODIFY/IN_DELETE con nombre ino2813 (wd={}), poll y epoll POLLIN solo con eventos, EAGAIN vacio, IN_IGNORED tras rm_watch, ENOENT/EINVAL verified", wd);
        } else {
            println!("[TEST 2813] inotify failed: ifd={} vacio={} wd={} noent={} p0={} epfd={} ectl={} e0={} noino={} f={} w={} u={} p1={} rev={} e1={} data={} cnt={} masks={:x?} nombres={} wds={} rm={} n2={} ign={:#x} rm2={}", ifd, vacio, wd, noent, p0, epfd, ectl, e0, noino, f, w, u, p1, pfd.revents, e1, evs[0].data, cnt, masks, nombres_ok, wds_ok, rm, n2, m_ign, rm2);
        }
    }

