        let w = if a >= 0 { portix_rt::syscall::sys_write(a, b"eco-srv".as_ptr(), 7) } else { -1 };
        let mut st = 0; waitpid(pid as i32, &mut st, 0);
        if a >= 0 { portix_rt::syscall::sys_close(a); }
        portix_rt::syscall::sys_close(srv);
        let hijo = portix_rt::wexitstatus(st);
