    // 3142. SCM_RIGHTS Descriptor Passing Protocol
    {
        // [CICLO 48] SCM_RIGHTS REAL: el hijo crea una tuberia, escribe en ella
        // "fd-viajero" y envia su extremo de LECTURA al padre por un socketpair
        // con sendmsg(SOL_SOCKET/SCM_RIGHTS); el padre lo recibe con recvmsg
        // como un fd NUEVO (distinto numero), lee de el los bytes y comprueba
        // que sobrevive al cierre del original en el hijo. Tambien: recvmsg sin
        // buffer de control -> MSG_CTRUNC y el fd se descarta; sendmsg con fd
        // invalido -> EBADF; sendmsg sobre un fichero -> ENOTSOCK.
        let mut sv = [0i32; 2];
        let rsp = portix_rt::syscall::sys_socketpair(1, 1, 0, sv.as_mut_ptr());
        let pid = fork();
        if pid == 0 {
            let mut pp = [0i32; 2];
            portix_rt::syscall::sys_pipe(pp.as_mut_ptr());
            portix_rt::syscall::sys_write(pp[1], b"fd-viajero".as_ptr(), 10);
            portix_rt::syscall::sys_close(pp[1]);
            let datos = b"hola";
            let iov = [datos.as_ptr() as usize, 4usize];
            let mut cmsg = [0u8; 24];
            cmsg[0..8].copy_from_slice(&20u64.to_ne_bytes()); // CMSG_LEN(4)
            cmsg[8..12].copy_from_slice(&1i32.to_ne_bytes());  // SOL_SOCKET
            cmsg[12..16].copy_from_slice(&1i32.to_ne_bytes()); // SCM_RIGHTS
            cmsg[16..20].copy_from_slice(&pp[0].to_ne_bytes());
            let hdr = portix_rt::syscall::MsgHdr { msg_name: 0, msg_namelen: 0, msg_iov: iov.as_ptr() as usize, msg_iovlen: 1, msg_control: cmsg.as_ptr() as usize, msg_controllen: 24, msg_flags: 0 };
            let s1 = portix_rt::syscall::sys_sendmsg(sv[1], &hdr as *const _, 0);
            portix_rt::syscall::sys_close(pp[0]); // el original muere; la copia viaja
            // Segundo envio: fd invalido -> EBADF; tercero: sin control, solo datos
            cmsg[16..20].copy_from_slice(&999i32.to_ne_bytes());
            let s2 = portix_rt::syscall::sys_sendmsg(sv[1], &hdr as *const _, 0);
            let hdr3 = portix_rt::syscall::MsgHdr { msg_name: 0, msg_namelen: 0, msg_iov: iov.as_ptr() as usize, msg_iovlen: 1, msg_control: 0, msg_controllen: 0, msg_flags: 0 };
            cmsg[16..20].copy_from_slice(&0i32.to_ne_bytes()); // stdin, para probar MSG_CTRUNC
            let hdr4 = portix_rt::syscall::MsgHdr { msg_name: 0, msg_namelen: 0, msg_iov: iov.as_ptr() as usize, msg_iovlen: 1, msg_control: cmsg.as_ptr() as usize, msg_controllen: 24, msg_flags: 0 };
            let s3 = portix_rt::syscall::sys_sendmsg(sv[1], &hdr3 as *const _, 0);
            let s4 = portix_rt::syscall::sys_sendmsg(sv[1], &hdr4 as *const _, 0);
            exit(if s1 == 4 && s2 == -9 && s3 == 4 && s4 == 4 { 0 } else { 20 });
        }
        let mut rx = [0u8; 4];
        let riov = [rx.as_mut_ptr() as usize, 4usize];
        let mut rc = [0u8; 32];
        let mut rh = portix_rt::syscall::MsgHdr { msg_name: 0, msg_namelen: 0, msg_iov: riov.as_ptr() as usize, msg_iovlen: 1, msg_control: rc.as_mut_ptr() as usize, msg_controllen: 32, msg_flags: 0 };
        let r1 = portix_rt::syscall::sys_recvmsg(sv[0], &mut rh as *mut _, 0);
        let clen = u64::from_ne_bytes([rc[0],rc[1],rc[2],rc[3],rc[4],rc[5],rc[6],rc[7]]);
        let lvl = i32::from_ne_bytes([rc[8],rc[9],rc[10],rc[11]]); let tp = i32::from_ne_bytes([rc[12],rc[13],rc[14],rc[15]]);
        let nuevo = i32::from_ne_bytes([rc[16],rc[17],rc[18],rc[19]]);
        let mut stt = 0; waitpid(pid as i32, &mut stt, 0);
        let mut viaje = [0u8; 16];
        let nv = if r1 == 4 && nuevo > 2 { portix_rt::syscall::sys_read(nuevo, viaje.as_mut_ptr(), 16) } else { -1 };
        let eof = if nv == 10 { portix_rt::syscall::sys_read(nuevo, viaje.as_mut_ptr(), 16) } else { -1 };
        if nuevo > 2 { portix_rt::syscall::sys_close(nuevo); }
        // Mensaje 3 (sin fds) y mensaje 4 (fd que no recogemos: MSG_CTRUNC)
        let mut rh3 = portix_rt::syscall::MsgHdr { msg_name: 0, msg_namelen: 0, msg_iov: riov.as_ptr() as usize, msg_iovlen: 1, msg_control: rc.as_mut_ptr() as usize, msg_controllen: 32, msg_flags: 0 };
        let r3 = portix_rt::syscall::sys_recvmsg(sv[0], &mut rh3 as *mut _, 0);
        let mut rh4 = portix_rt::syscall::MsgHdr { msg_name: 0, msg_namelen: 0, msg_iov: riov.as_ptr() as usize, msg_iovlen: 1, msg_control: 0, msg_controllen: 0, msg_flags: 0 };
        let r4 = portix_rt::syscall::sys_recvmsg(sv[0], &mut rh4 as *mut _, 0);
        let ff = portix_rt::syscall::sys_open(b"/tmp\0".as_ptr(), 0) as i32;
        let notsock = portix_rt::syscall::sys_sendmsg(ff, &rh3 as *const _, 0);
        portix_rt::syscall::sys_close(ff); portix_rt::syscall::sys_close(sv[0]); portix_rt::syscall::sys_close(sv[1]);
        let hijo = portix_rt::wexitstatus(stt);
        if rsp == 0 && r1 == 4 && &rx == b"hola" && rh.msg_controllen == 24 && clen == 20 && lvl == 1 && tp == 1 && nuevo > 2 && nuevo != sv[0] && nuevo != sv[1]
            && nv == 10 && &viaje[..10] == b"fd-viajero" && eof == 0 && r3 == 4 && rh3.msg_controllen == 0 && r4 == 4 && (rh4.msg_flags & 0x8) != 0 && notsock == -88 && hijo == 0 {
            println!("[TEST 3142] SCM_RIGHTS real: el padre recibe por recvmsg un fd nuevo ({}) con el extremo de tuberia enviado por el hijo, lee 'fd-viajero' tras el cierre del original, EBADF/ENOTSOCK y MSG_CTRUNC sin buffer de control verified", nuevo);
        } else {
            println!("[TEST 3142] scm_rights failed: sp={} r1={} rx={:?} clen={} hdrlen={} lvl={} tp={} nuevo={} nv={} eof={} r3={} c3={} r4={} f4={:#x} notsock={} hijo={}", rsp, r1, rx, clen, rh.msg_controllen, lvl, tp, nuevo, nv, eof, r3, rh3.msg_controllen, r4, rh4.msg_flags, notsock, hijo);
        }
    }

    // 3143. Named Pipe FIFO Creation Semantics (S_IFIFO)
    {
        // [CICLO 48] FIFO con nombre REAL: mknod(S_IFIFO) crea un nodo cuyo
        // stat dice S_IFIFO; el hijo abre O_WRONLY y escribe; el padre abre
        // O_RDONLY, lee los mismos bytes y recibe EOF al cerrar el hijo.
        // Tambien: O_WRONLY|O_NONBLOCK sin lector -> ENXIO; mknod repetido -> EEXIST.
        let ruta = b"/tmp/fifo3143\0";
        let _ = portix_rt::syscall::sys_unlink(ruta.as_ptr());
        let rm = portix_rt::syscall::sys_mknod(ruta.as_ptr(), 0o010000 | 0o644, 0);
        let rdup = portix_rt::syscall::sys_mknod(ruta.as_ptr(), 0o010000 | 0o644, 0);
        let mut st = [0u8; 144];
        let rs = portix_rt::syscall::sys_stat(ruta.as_ptr(), st.as_mut_ptr());
        let modo = u32::from_le_bytes([st[24], st[25], st[26], st[27]]);
        let enxio = portix_rt::syscall::sys_open(ruta.as_ptr(), 0x1 | 0x800);
        let pid = fork();
        if pid == 0 {
            let w = portix_rt::syscall::sys_open(ruta.as_ptr(), 0x1) as i32;
            let n = if w >= 0 { portix_rt::syscall::sys_write(w, b"fifo-3143".as_ptr(), 9) } else { -1 };
            if w >= 0 { portix_rt::syscall::sys_close(w); }
            exit(if n == 9 { 0 } else { 7 });
        }
        let r = portix_rt::syscall::sys_open(ruta.as_ptr(), 0x0) as i32;
        let mut buf = [0u8; 16];
        let n = if r >= 0 { portix_rt::syscall::sys_read(r, buf.as_mut_ptr(), 16) } else { -1 };
        let mut stt = 0; waitpid(pid as i32, &mut stt, 0);
        let eof = if r >= 0 { portix_rt::syscall::sys_read(r, buf.as_mut_ptr(), 16) } else { -1 };
        if r >= 0 { portix_rt::syscall::sys_close(r); }
        let hijo = portix_rt::wexitstatus(stt);
        let _ = portix_rt::syscall::sys_unlink(ruta.as_ptr());
        if rm == 0 && rdup == -17 && rs == 0 && (modo & 0o170000) == 0o010000 && enxio == -6 && r >= 0 && n == 9 && &buf[..9] == b"fifo-3143" && eof == 0 && hijo == 0 {
            println!("[TEST 3143] FIFO con nombre real: mknod S_IFIFO (stat modo=0{:o}), EEXIST, ENXIO sin lector, hijo escribe 9 bytes y padre los lee por la ruta con EOF al cerrar verified", modo);
        } else {
            println!("[TEST 3143] fifo failed: mknod={} dup={} stat={} modo=0{:o} enxio={} r={} n={} eof={} hijo={}", rm, rdup, rs, modo, enxio, r, n, eof, hijo);
        }
    }

