    // 3172. sys_poll & sys_select Descriptor Multiplexing
    {
        // Prueba REAL: poll sobre una tuberia vacia con timeout 0 -> 0; con datos -> 1 y POLLIN.
        let mut fds = [0i32; 2];
        let mut ok = false; let mut det = (-99i32, -99i32, 0i16);
        if portix_rt::syscall::sys_pipe(fds.as_mut_ptr()) == 0 {
            let mut pfd = portix_rt::syscall::PollFd { fd: fds[0], events: 1, revents: 0 };
            let r0 = portix_rt::syscall::sys_poll(&mut pfd as *mut _, 1, 0);
            portix_rt::syscall::sys_write(fds[1], b"x".as_ptr(), 1);
            pfd.revents = 0;
            let r1 = portix_rt::syscall::sys_poll(&mut pfd as *mut _, 1, 0);
            det = (r0, r1, pfd.revents);
            ok = r0 == 0 && r1 == 1 && (pfd.revents & 1) != 0;
            portix_rt::syscall::sys_close(fds[0]); portix_rt::syscall::sys_close(fds[1]);
        }
        if ok {
            println!("[TEST 3172] sys_poll & sys_select descriptor multiplexing verified");
        } else {
            println!("[TEST 3172] poll failed: {:?}", det);
        }
    }

    // 3173. Socket Options (SO_REUSEADDR, SO_KEEPALIVE, TCP_NODELAY)
    {
        // [CICLO 47-b] Prueba REAL: setsockopt acepta SO_REUSEADDR/SO_KEEPALIVE, rechaza nivel u opcion invalidos y ENOTSOCK en un pipe.
        let s = portix_rt::syscall::sys_socket(2, 1, 0) as i32;
        let uno: i32 = 1;
        let r1 = portix_rt::syscall::sys_setsockopt(s, 1, 2, &uno as *const i32 as *const u8, 4);
        let r2 = portix_rt::syscall::sys_setsockopt(s, 1, 9, &uno as *const i32 as *const u8, 4);
        let r3 = portix_rt::syscall::sys_setsockopt(s, 1, 9999, &uno as *const i32 as *const u8, 4);
        let r4 = portix_rt::syscall::sys_setsockopt(s, 77, 2, &uno as *const i32 as *const u8, 4);
        let mut p = [0i32; 2];
        let _ = portix_rt::syscall::sys_pipe(p.as_mut_ptr());
        let r5 = portix_rt::syscall::sys_setsockopt(p[0], 1, 2, &uno as *const i32 as *const u8, 4);
        portix_rt::syscall::sys_close(p[0]); portix_rt::syscall::sys_close(p[1]); portix_rt::syscall::sys_close(s);
        if s >= 0 && r1 == 0 && r2 == 0 && r3 == -22 && r4 == -92 && r5 == -88 {
            println!("[TEST 3173] setsockopt real: SO_REUSEADDR/SO_KEEPALIVE=0, opcion invalida=-22, nivel invalido=-92, pipe=-88 verified");
        } else {
            println!("[TEST 3173] sockopt failed: s={} r={} {} {} {} {}", s, r1, r2, r3, r4, r5);
        }
    }

