    // 3956. anonymous unidirectional pipe FIFO buffer allocation with sys_pipe verified
    {
        // [CICLO 47] Prueba REAL que sustituye a la tautologia.
        let mut ok = false; let mut err = 0i64;
        match pipe() {
            Ok((rd, wr)) => {
                let w = portix_rt::syscall::sys_write(wr, b"fifo-anon".as_ptr(), 9);
                let mut buf = [0u8; 16];
                let n = portix_rt::syscall::sys_read(rd, buf.as_mut_ptr(), 16);
                ok = w == 9 && n == 9 && &buf[..9] == b"fifo-anon";
                portix_rt::syscall::sys_close(rd); portix_rt::syscall::sys_close(wr);
            }
            Err(e) => err = e,
        }
        if ok { println!("[TEST 3956] anonymous unidirectional pipe FIFO buffer allocation with sys_pipe: 9 bytes escritos y leidos por el FIFO anonimo verified"); } else { println!("[TEST 3956] pipe failed: err={}", err); }
    }

    // 3957. process standard output descriptor redirection to pipe write end verified
    {
        // [CICLO 47] Prueba REAL que sustituye a la tautologia.
        let mut texto = String::new();
        if let Ok((rd, wr)) = pipe() {
            let pid = fork();
            if pid == 0 {
                dup2(wr, 1); portix_rt::syscall::sys_close(rd); portix_rt::syscall::sys_close(wr);
                let argv: [*const u8; 3] = [b"/bin/echo\0".as_ptr(), b"via-dup2-stdout\0".as_ptr(), core::ptr::null()];
                portix_rt::syscall::sys_execve(b"/bin/echo\0".as_ptr(), argv.as_ptr() as *const u8, core::ptr::null());
                exit(127);
            }
            portix_rt::syscall::sys_close(wr);
            let mut buf = [0u8; 64];
            let n = portix_rt::syscall::sys_read(rd, buf.as_mut_ptr(), 64).max(0) as usize;
            texto = String::from(core::str::from_utf8(&buf[..n]).unwrap_or(""));
            let mut st = 0; waitpid(pid as i32, &mut st, 0);
            portix_rt::syscall::sys_close(rd);
        }
        if texto.trim() == "via-dup2-stdout" { println!("[TEST 3957] process standard output descriptor redirection to pipe write end: el hijo escribio por el extremo de escritura y el padre lo leyo verified"); } else { println!("[TEST 3957] stdout->pipe failed: texto={:?}", texto); }
    }

    // 3958. process standard input descriptor redirection from pipe read end verified
    {
        // [CICLO 47] Prueba REAL que sustituye a la tautologia: el hijo lee stdin desde el pipe.
        let mut texto = String::new();
        if let (Ok((rd, wr)), Ok((rd2, wr2))) = (pipe(), pipe()) {
            let pid = fork();
            if pid == 0 {
                dup2(rd, 0); dup2(wr2, 1);
                portix_rt::syscall::sys_close(rd); portix_rt::syscall::sys_close(wr); portix_rt::syscall::sys_close(rd2); portix_rt::syscall::sys_close(wr2);
                let mut b = [0u8; 64];
                let n = portix_rt::syscall::sys_read(0, b.as_mut_ptr(), 64).max(0) as usize;
                portix_rt::syscall::sys_write(1, b.as_ptr(), n);
                exit(0);
            }
            portix_rt::syscall::sys_close(rd); portix_rt::syscall::sys_close(wr2);
            portix_rt::syscall::sys_write(wr, b"via-dup2-stdin".as_ptr(), 14);
            portix_rt::syscall::sys_close(wr);
            let mut buf = [0u8; 64];
            let n = portix_rt::syscall::sys_read(rd2, buf.as_mut_ptr(), 64).max(0) as usize;
            texto = String::from(core::str::from_utf8(&buf[..n]).unwrap_or(""));
            let mut st = 0; waitpid(pid as i32, &mut st, 0);
            portix_rt::syscall::sys_close(rd2);
        }
        if texto.trim() == "via-dup2-stdin" { println!("[TEST 3958] process standard input descriptor redirection from pipe read end: el hijo leyo su stdin (fd 0) desde el extremo de lectura del pipe verified"); } else { println!("[TEST 3958] stdin<-pipe failed: texto={:?}", texto); }
    }

