    // 4007. Read-Only PTE Protection Mutation on Fork
    {
        // [CICLO 47] Prueba REAL que sustituye a la tautologica retirada en el ciclo 46.
        // Tras fork, la primera escritura del PADRE tambien debe copiar (ambos comparten solo lectura).
        let mut dato: Vec<u32> = alloc::vec![7u32; 2048];
        let pid = fork();
        if pid == 0 {
            sleep(1);
            exit(if dato[1000] == 7 { 0 } else { 1 }); // el hijo no debe ver la escritura del padre
        }
        dato[1000] = 99;
        let mut st = 0;
        waitpid(pid as i32, &mut st, 0);
        if pid > 0 && dato[1000] == 99 && portix_rt::wexitstatus(st) == 0 {
            println!("[TEST 4007] PTE de solo lectura tras fork: la escritura del padre no se filtra al hijo verified");
        } else {
            println!("[TEST 4007] ro-pte fork failed: padre={} st={}", dato[1000], st);
        }
    }

