    // 4011. Demand Paging Lazy Allocation on First Access
    {
        // [CICLO 47] Prueba REAL que sustituye a la tautologica retirada en el ciclo 46.
        // mmap anonimo de 8 MiB: solo se materializan las paginas tocadas.
        let len = 8 * 1024 * 1024;
        let p = portix_rt::syscall::sys_mmap(0, len, 3, 0x22);
        let mut ok = false;
        if p > 0 {
            let base = p as usize as *mut u8;
            unsafe {
                *base.add(len - 1) = 0x42;
                *base.add(0) = 0x24;
                ok = *base.add(len - 1) == 0x42 && *base.add(0) == 0x24 && *base.add(len / 2) == 0;
            }
            let _ = portix_rt::syscall::sys_munmap(p as usize, len);
        }
        if ok {
            println!("[TEST 4011] paginacion por demanda: 8 MiB mapeados, primera y ultima pagina escritas, el medio lee 0 verified");
        } else {
            println!("[TEST 4011] demand paging failed: p={}", p);
        }
    }

