    // 4231. eventfd 64-bit Non-Blocking Counter Synchronization
    {
        // [CICLO 48] eventfd REAL no bloqueante: lectura devuelve el contador y
        // lo pone a cero; vacio -> EAGAIN; las escrituras suman; u64::MAX ->
        // EINVAL; desbordar -> EAGAIN; tamanos < 8 -> EINVAL; poll ve POLLIN
        // solo con contador > 0; una lectura BLOQUEANTE espera al hijo.
        let efd = portix_rt::syscall::sys_eventfd2(5, 0x800) as i32;
        let mut v = [0u8; 8];
        let r1 = portix_rt::syscall::sys_read(efd, v.as_mut_ptr(), 8); let v1 = u64::from_ne_bytes(v);
        let r2 = portix_rt::syscall::sys_read(efd, v.as_mut_ptr(), 8);
        let w3 = portix_rt::syscall::sys_write(efd, 3u64.to_ne_bytes().as_ptr(), 8);
        let w4 = portix_rt::syscall::sys_write(efd, 4u64.to_ne_bytes().as_ptr(), 8);
        let mut pfd = portix_rt::syscall::PollFd { fd: efd, events: 1, revents: 0 };
        let rp1 = portix_rt::syscall::sys_poll(&mut pfd as *mut _, 1, 0); let rev1 = pfd.revents;
        let r3 = portix_rt::syscall::sys_read(efd, v.as_mut_ptr(), 8); let v3 = u64::from_ne_bytes(v);
        pfd.revents = 0; let rp2 = portix_rt::syscall::sys_poll(&mut pfd as *mut _, 1, 0); let rev2 = pfd.revents;
        let wmax = portix_rt::syscall::sys_write(efd, u64::MAX.to_ne_bytes().as_ptr(), 8);
        let wcasi = portix_rt::syscall::sys_write(efd, (u64::MAX - 1).to_ne_bytes().as_ptr(), 8);
        let wover = portix_rt::syscall::sys_write(efd, 1u64.to_ne_bytes().as_ptr(), 8);
        let r4 = portix_rt::syscall::sys_read(efd, v.as_mut_ptr(), 8); let v4 = u64::from_ne_bytes(v);
        let wcorto = portix_rt::syscall::sys_write(efd, v.as_ptr(), 4);
        let rcorto = portix_rt::syscall::sys_read(efd, v.as_mut_ptr(), 4);
        portix_rt::syscall::sys_close(efd);
        let bfd = portix_rt::syscall::sys_eventfd2(0, 0) as i32;
        let pid = fork();
        if pid == 0 { portix_rt::syscall::sys_sched_yield(); let w = portix_rt::syscall::sys_write(bfd, 42u64.to_ne_bytes().as_ptr(), 8); exit(if w == 8 { 0 } else { 5 }); }
        let rb = portix_rt::syscall::sys_read(bfd, v.as_mut_ptr(), 8); let vb = u64::from_ne_bytes(v);
        let mut stt = 0; waitpid(pid as i32, &mut stt, 0);
        portix_rt::syscall::sys_close(bfd);
        if efd >= 0 && r1 == 8 && v1 == 5 && r2 == -11 && w3 == 8 && w4 == 8 && rp1 == 1 && (rev1 & 1) != 0 && r3 == 8 && v3 == 7
            && rp2 == 0 && rev2 == 0 && wmax == -22 && wcasi == 8 && wover == -11 && r4 == 8 && v4 == u64::MAX - 1
            && wcorto == -22 && rcorto == -22 && bfd >= 0 && rb == 8 && vb == 42 && portix_rt::wexitstatus(stt) == 0 {
            println!("[TEST 4231] eventfd real: contador 64 bits (5 leido y reseteado, EAGAIN vacio, 3+4=7, poll POLLIN solo con valor, u64::MAX EINVAL, desborde EAGAIN, tamanos cortos EINVAL) y lectura bloqueante que espera los 42 del hijo verified");
        } else {
            println!("[TEST 4231] eventfd failed: efd={} r1={} v1={} r2={} w3={} w4={} rp1={} rev1={} r3={} v3={} rp2={} rev2={} wmax={} wcasi={} wover={} r4={} v4={:#x} wcorto={} rcorto={} rb={} vb={} hijo={}", efd, r1, v1, r2, w3, w4, rp1, rev1, r3, v3, rp2, rev2, wmax, wcasi, wover, r4, v4, wcorto, rcorto, rb, vb, portix_rt::wexitstatus(stt));
        }
    }

    // 4232. eventfd Atomic Read and Reset Counter Operations
    {
        // [CICLO 48] eventfd REAL: modo normal lee-y-resetea (3 -> 3, luego
        // EAGAIN); EFD_SEMAPHORE decrementa de uno en uno (3 -> 1,1,1, EAGAIN);
        // el descriptor duplicado comparte el contador; bandera invalida -> EINVAL.
        let a = portix_rt::syscall::sys_eventfd2(3, 0x800);
        let mut v = [0u8; 8];
        let ra = portix_rt::syscall::sys_read(a, v.as_mut_ptr(), 8); let va = u64::from_ne_bytes(v);
        let ra2 = portix_rt::syscall::sys_read(a, v.as_mut_ptr(), 8);
        let s = portix_rt::syscall::sys_eventfd2(3, 0x800 | 1);
        let mut vals = [0u64; 3]; let mut rs = [0i64; 3];
        for i in 0..3 { rs[i] = portix_rt::syscall::sys_read(s, v.as_mut_ptr(), 8); vals[i] = u64::from_ne_bytes(v); }
        let rs4 = portix_rt::syscall::sys_read(s, v.as_mut_ptr(), 8);
        let d = portix_rt::syscall::sys_dup(s) as i32;
        let wd = portix_rt::syscall::sys_write(d, 2u64.to_ne_bytes().as_ptr(), 8);
        let rd1 = portix_rt::syscall::sys_read(s, v.as_mut_ptr(), 8); let vd1 = u64::from_ne_bytes(v);
        let rd2 = portix_rt::syscall::sys_read(d, v.as_mut_ptr(), 8); let vd2 = u64::from_ne_bytes(v);
        let rd3 = portix_rt::syscall::sys_read(s, v.as_mut_ptr(), 8);
        let inval = portix_rt::syscall::sys_eventfd2(0, 0x10);
        portix_rt::syscall::sys_close(a); portix_rt::syscall::sys_close(s); portix_rt::syscall::sys_close(d);
        if a >= 0 && ra == 8 && va == 3 && ra2 == -11 && s >= 0 && rs == [8, 8, 8] && vals == [1, 1, 1] && rs4 == -11
            && d >= 0 && wd == 8 && rd1 == 8 && vd1 == 1 && rd2 == 8 && vd2 == 1 && rd3 == -11 && inval == -22 {
            println!("[TEST 4232] eventfd real: lectura atomica con reseteo (3->3, EAGAIN), EFD_SEMAPHORE decrementa 1,1,1 y EAGAIN, dup comparte el contador, bandera invalida EINVAL verified");
        } else {
            println!("[TEST 4232] eventfd sem failed: a={} ra={} va={} ra2={} s={} rs={:?} vals={:?} rs4={} d={} wd={} rd1={} vd1={} rd2={} vd2={} rd3={} inval={}", a, ra, va, ra2, s, rs, vals, rs4, d, wd, rd1, vd1, rd2, vd2, rd3, inval);
        }
    }

